recipes.code:
{
  "inputs": [
    {
      "id": "siteglass-api-key",
      "type": "promptString",
      "description": "siteglass API key (optional; the server auto-creates an account if absent).",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "siteglass-mcp@0.1.5"
      ],
      "env": {
        "SITEGLASS_API_KEY": "${input:siteglass-api-key}",
        "SITEGLASS_BASE_URL": "<siteglass-base-url>"
      }
    }
  }
}
